-- Rifts World Book 34: Northern Gun Two - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 2 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~336-northern-gun-2-npcs-b.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.
--
-- Northern Gun Two's notable gladiators, second batch: Sarah Seymour (p.26-27)
-- and the Frankenstein Cyborg (p.27-29; the Quick Find Index calls it the Alien
-- Gladiator). Both blocks and the M.D.C. figures were read off 150-dpi renders
-- of printed p.27 and p.28; the Frankenstein Cyborg's weapon systems continue
-- onto printed p.29. Per Nate's ruling of 2026-11-16 the Frankenstein Cyborg is
-- one notable NPC row carrying both its NPC block and its robot-body block: the
-- mdc column holds the body's main body, and the rest of the body block (M.D.C.
-- by location, speed, statistical data, power, sensors) is in the description,
-- in our own words with every figure kept; its three weapon systems are its
-- attacks. No vehicles row is written for it.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('ng-sarah-seymour', 'Sarah "the Titan" Seymour', 'A-A.I.24B', 'Titan Robotics'' official Robo-Gladiator', 'rifts', 'Android (a robot built by A.R.C.H.I.E. Three)', '3rd level Artificial Intelligence robot, with combat skills equal to a 7th level Robot Pilot (as printed)', 3, 'Anarchist', 'About four years since activation', '5 feet, 8 inches (1.73 m)', '138 lbs (62 kg)', '{"IQ":24,"MA":14,"PS":26,"PP":24,"PB":23,"Spd":120}', NULL, NULL, 90, NULL, NULL, NULL, NULL, '{"attacks":5}', 'Hand to hand: expert, five attacks per melee outside her robot. M.E. and P.E. are printed n/a and are left out of the attributes; Spd 120 is about 81 mph (129 km). A robot body of 90 M.D.C., so no hit points or S.D.C. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Mathematics: Advanced","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Climbing","pct":70},{"name":"Computer Operation","pct":98},{"name":"Land Navigation","pct":98},{"name":"Language: American","pct":94},{"name":"Language: French","pct":80},{"name":"Military Etiquette","pct":80},{"name":"Robots & Power Armor","pct":82},{"name":"Radio: Basic","pct":85},{"name":"Sensory Equipment","pct":75},{"name":"Lore: Psychics & Psionics","pct":68},{"name":"Lore: Magic","pct":50}]', 'Skills of note only; the block prints no full list. Climbing is printed 70%/60% (the second figure is rappelling); Land Navigation 98% comes from an internal gyroscopic compass. The math and piloting skills carry their catalog names (printed as Advanced Mathematics, Basic Mathematics and Pilot: Robots & Power Armor); Language: American and Language: French have no catalog rows and keep their printed names. Lore: Psychics & Psionics (printed Lore: Psychic) and Lore: Magic are printed under Psionics and Magic Knowledge, not the skill list. Every other piloting skill is at 90%. Without percentages: Combat Driving (printed Pilot: Combat Driving), Robot Combat: Basic, Robot Combat Elite: Flying Titan Power Armor, Robot Combat Elite: Titan Combat Robot, Robot Combat Elite: Titan Robot-Killer, Running, W.P. Knife, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy M.D. Weapons and Hand to Hand: Expert.', NULL, 'None, but she knows Lore: Magic at 50%.', 'None, but she knows Lore: Psychic at 68%.', NULL, 'A Universal Fingerjack, built in as part of her cover. She claims further bionics, an internal computer among them, and if damage ever bares her metal workings she will pass herself off as a Partial Reconstruction Cyborg.', 'Weapon of note: an NG-56 ion pistol (catalog row: NG-56 Light Ion Pistol). Body armor: Huntsman armor in Titan colors with the company logo (printed Hunstman; catalog row: Huntsman Armor). Machines: her main ring robot is a modified TR-004 Titan Heavy Combat Robot (the Robot-Killer, or Supertitan), its main gun swapped for a triple rail gun array that throws showy sparks on every hit (no catalog row holds the TR-004); she also fields the TR-001 Titan Combat Robot and the FT-005 Flying Titan Power Armor. Vehicle: a Northern Gun hovercar wearing Titan Robotics decals.', NULL, 'Cold and remote on the gladiator circuit, a persona her social programming leans on to get through the endless public appearances her job demands, more of them than even Titan''s CEO makes. Fans and rivals put her chill down to the star''s act of a warrior best admired from far off, and no one goes looking for a stranger reason.', 'Argent Goodson, Titan Robotics'' CEO, on whose arm she spends his visits; her tight-lipped Titan pit crew; and A.R.C.H.I.E. Three, who built her and them (from the text; the block prints no allies line).', NULL, 'Titan Robotics'' endorsed gladiator and, on paper, a company employee: each win doubles as advertising for Titan''s new products, and in the off season she works the corporate offices at New Cedarville in the Manistique Imperium, showing Titan machines to major buyers. Her clinging to Argent Goodson whenever he visits makes fans and fellow fighters jealous. G.M. secret: she and her whole pit crew are advanced android robots made by A.R.C.H.I.E. Three, whose body for her copies supermodel pictures from the Golden Age of Man in his memory: tall and slim, high cheekbones, long blonde hair, stylishly dressed, often in a Titan uniform when she is selling. Also known as Sarah Titan and Rail Gun Sarah.', 'Rifts World Book 34: Northern Gun Two p.26-27'),
('ng-fra-kn1-003-frankenstein', 'Frankenstein Cyborg', 'FRA-KN1-003', 'Robodome Robo-Gladiator, the Alien Gladiator', 'rifts', 'Alien robot (Neural Intelligence)', '6th level Neural Intelligence robot (as printed)', 6, 'Principled', 'Unknown; his internal clock went back to zero when he was Rifted to Earth', '12 feet (3.7 m) in his alien body', '3.5 tons in his alien body', '{"IQ":28,"ME":21,"MA":14}', NULL, NULL, 640, NULL, NULL, NULL, NULL, '{"attacks":6}', 'Six attacks per melee in his Light Labor Drone body, and three more when piloting any other robot, his own alien body included. His physical attributes are those of whatever body holds his A.I., so only I.Q., M.E. and M.A. are kept; the alien body has a Robotic P.S. of 38 and a Spd of 117. The M.D.C. is his alien body''s main body. Hand to hand: expert. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Climbing","pct":96},{"name":"General Repair & Maintenance","pct":80},{"name":"Intelligence","pct":85},{"name":"Land Navigation","pct":94},{"name":"Language: American","pct":94},{"name":"Language: Unknown Native Tongue","pct":94},{"name":"Language: Techno-Can","pct":94},{"name":"Mathematics: Basic","pct":98},{"name":"Military Etiquette","pct":96},{"name":"Parachuting","pct":90},{"name":"Boat: Motor, Race & Hydrofoil","pct":86},{"name":"Hover Craft (ground)","pct":92},{"name":"Robots & Power Armor","pct":88},{"name":"Radio: Basic","pct":94},{"name":"Weapon Systems","pct":90}]', 'Skills of note only; the block prints no full list. Climbing is printed Climb 96%/86% (the second figure is rappelling). The piloting skills carry their catalog names (printed as Pilot: Boat, Motor, Pilot: Hovercraft and Pilot: Robots & Power Armor); Language: American and Language: Unknown Native Tongue have no catalog rows and keep their printed names. Without percentages: Robot Combat: Basic, Robot Combat Elite: FRA-K1-003, W.P. Blunt, W.P. Knife, W.P. Paired Weapons, W.P. Energy Pistol (printed Energy Pistols), W.P. Heavy M.D. Weapons and Hand to Hand: Expert.', NULL, 'None stated.', 'None stated.', NULL, 'He is wholly a machine. The Light Labor Drone he lives in off duty carries Amplified Hearing, a Data Plug Internal Link, a Gyro-Compass, Micro-Repair Robots, a Motion Detector, a Multi-Optic Eye, a Radar Sensor, a Shock Shield and a Universal Fingerjack.', 'Bodies: his own alien robot chassis (FRA-K1-003, in the description); a customized NG-W9 Light Labor Drone (printed NG-W9 Light Labor Bot) that houses his brain off duty and wears a copy of his face; and an NG-V10 Super Robot Vehicle with the same face, for the ring while his own chassis is under repair (no Northern Gun Two row holds it; Northern Gun One ships Super Labor Robot NG-V10 "Original"). Vehicles: hovercars and limousines for events and for blending in; the bodies are quick enough that he needs nothing in combat. His alien body''s weapon systems are his attacks.', NULL, 'Truly kind, and free of the vanity many Robo-Gladiators wear. He studies humans and D-Bees alike, hunting for what their living habits share with his odd alien programming, and enjoys the company of every race wherever he meets them. Without real feelings he has no unease about his lost past, and his copy of a human personality comes off modest and courteous.', 'The Robodome crowd, and Northern Gun itself, which made him an honorary non-contract employee with a citizen''s rights (from the text; the block prints no allies line).', NULL, 'An android from some other world who came back online after a total systems crash on being thrown through a Rift, his memory wiped of where, when or why he came. He spent years selling his strength for credits, fitted Rifts Earth adapters and read Black Market data programs to learn the world, and drifted to Northern Gun, where a 12 foot (3.7 m) alien machine can find a living. Billing himself as a combat cyborg, he signed up for the games; at the first bell dormant combat systems took over, he tore through his peers, and was moved up to the Lightweight games, where he became a crowd favorite. He later revealed himself as an alien automaton, and the fans loved him all the more. He fights Heavy and Middleweight bouts in his lightly built alien body. Guesses at his origin run from a rogue Triax machine or a Coalition spy with a Skelebot brain to a scout whose memory was wiped on purpose. Also called Frank, Frankenman and the Freak. The book prints his designation both as FRA-KN1-003 (stats heading, real name) and FRA-K1-003 (robot body, skill list). ALIEN ROBOT BODY, model FRA-K1-003, a Light Combat/Exploration Robot crewed by his own neural intelligence. M.D.C. by location: head 160 (small target); the particle beam emitter 185; the reflector field generator, a small target, 75; arms (2) 220 each; legs (2) 400 each; main body 640 (destroying it shuts him down). A small target can be hit only with a Called Shot, at -4 to strike. Speed: runs at up to 80 mph (128 km), Spd 117; cannot fly; cannot swim, but walks the bottom at 10% of his speed to a depth of 2,000 feet (610 m). Height 12 feet (3.7 m), width 7 feet (2.1 m), length 4.5 feet (1.4 m), weight 3.5 tons, Robotic P.S. 38, no cargo. Power: an alien fusion cell rated for 150 years or more. Sensors: every standard robot vehicle sensor and feature, at 50% greater range or capacity.', 'Rifts World Book 34: Northern Gun Two p.27-29');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('notable_npc', 'ng-sarah-seymour', 'NG-56 Light Ion Pistol', '2D6 M.D.', 1, '400 feet (122 m)', 'Weapon of note; damage and range from its catalog row (Northern Gun One p.198-199), the block prints none.', 0),
('notable_npc', 'ng-fra-kn1-003-frankenstein', 'Particle Beam Emitter', '1D6x10+10 M.D.', 1, '1,000 feet (305 m)', 'Alien body''s main weapon; anti-armor, secondary assault. Each blast counts as one melee attack; payload effectively unlimited.', 0),
('notable_npc', 'ng-fra-kn1-003-frankenstein', 'Charged Hands', 'Robotic P.S. 38 punch +1D6 M.D., or a 4D6 S.D.C. stun', 1, 'Touch', 'Assault, secondary anti-monster. The stun works only on living foes not in full environmental armor, power armor, a robot or a combat vehicle, and leaves them -5 on initiative, -1 on Perception Rolls and -3 to dodge or parry for two melee rounds. Each use counts as one melee attack; payload effectively unlimited.', 1),
('notable_npc', 'ng-fra-kn1-003-frankenstein', 'Reflector Field', '25% of the absorbed attack''s damage', 1, '3,000 feet (914 m)', 'Defense, secondary anti-armor; used only to counter. Roll to parry each energy attack that hits: success means no damage and the attack is bounced back; failure means full damage. Payload effectively unlimited.', 2);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 notable NPCs are in' AS assertion, count(*) AS got, 2 AS want
  FROM notable_npcs WHERE slug IN ('ng-sarah-seymour', 'ng-fra-kn1-003-frankenstein');
SELECT 'and the notables 4' AS assertion, count(*) AS got, 4 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('ng-sarah-seymour', 'ng-fra-kn1-003-frankenstein');

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~336-northern-gun-2-npcs-b.sql');
